import org.junit.runner.*;import org.junit.runner.notification.*;import java.nio.file.*;import java.util.*;
public class JUnitReportRunner {
 static String xml(String s){return s.replace("&","&amp;").replace("<","&lt;").replace("\"","&quot;");}
 public static void main(String[] args)throws Exception{Path out=Paths.get("verification/results/junit");Files.createDirectories(out);List<String> cases=new ArrayList<>();JUnitCore core=new JUnitCore();core.addListener(new RunListener(){long start;Failure failure;public void testStarted(Description d){start=System.nanoTime();failure=null;System.out.println("START "+d.getMethodName());}public void testFailure(Failure f){failure=f;System.out.println(f.getTrace());}public void testFinished(Description d){double seconds=(System.nanoTime()-start)/1e9;cases.add("<testcase classname=\""+d.getClassName()+"\" name=\""+d.getMethodName()+"\" time=\""+seconds+"\">"+(failure==null?"":"<failure message=\""+xml(failure.getMessage()==null?"failure":failure.getMessage())+"\"><![CDATA["+failure.getTrace()+"]]></failure>")+"</testcase>");System.out.println((failure==null?"PASS ":"FAIL ")+d.getMethodName());}});Result result=core.run(Class.forName(args.length>0?args[0]:"FullFunctionalTest"));String doc="<?xml version=\"1.0\" encoding=\"UTF-8\"?><testsuite tests=\""+result.getRunCount()+"\" failures=\""+result.getFailureCount()+"\" time=\""+result.getRunTime()/1000.0+"\">"+String.join("\n",cases)+"</testsuite>";Files.write(out.resolve(args.length>0?args[0]+".xml":"TEST-full-functional.xml"),doc.getBytes("UTF-8"));System.out.println("JUnit: tests="+result.getRunCount()+" failures="+result.getFailureCount());if(!result.wasSuccessful())System.exit(1);}
}
